16	package org.springframework.samples.petclinic.model;
17	
18	import java.nio.charset.StandardCharsets;
19	import java.security.MessageDigest;
20	import java.security.NoSuchAlgorithmException;
21	
22	/**
23	 * The deterministic household identifier: the first 12 upper-case hex characters of SHA-256 over the
24	 * normalized last name and postcode joined with '|'. Owners with the same last name and postcode
25	 * share it automatically, so it is the single key for household membership and duplicate detection.
26	 */
27	public final class Household {
28	
29	    private Household() {
30	    }
31	
32	    /** The household id for the given last name and postcode, or null when either is absent. */
33	    public static String id(String lastName, String postcode) {
34	        if (lastName == null || postcode == null) {
35	            return null;
36	        }
37	        String key = lastName.strip().replaceAll("\\s+", " ").toLowerCase() + '|' + postcode;
38	        StringBuilder sb = new StringBuilder();
39	        for (byte b : sha256(key)) {
40	            sb.append(String.format("%02X", b));
41	        }
42	        return sb.substring(0, 12);
43	    }
44	
45	    private static byte[] sha256(String value) {
46	        try {
47	            return MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));
48	        } catch (NoSuchAlgorithmException e) {
49	            throw new IllegalStateException(e);
50	        }
51	    }
52	}
