28	/**
29	 * Rejects an owner whose email address uses a disposable-domain provider. The domain is compared
30	 * case-insensitively against a small blocklist; an owner with no email is left untouched.
31	 */
32	@ControllerAdvice
33	public class OwnerDisposableEmailAdvice implements Validator {
34	
35	    private static final Set<String> BLOCKED_DOMAINS = Set.of(
36	        "mailinator.com", "tempmail.com", "guerrillamail.com");
37	
38	    @InitBinder
39	    void registerOwnerDisposableEmailValidator(WebDataBinder binder) {
40	        binder.addValidators(this);
41	    }
42	
43	    @Override
44	    public boolean supports(Class<?> clazz) {
45	        return OwnerFieldsDto.class.isAssignableFrom(clazz);
46	    }
47	
48	    @Override
49	    public void validate(Object target, Errors errors) {
50	        String email = ((OwnerFieldsDto) target).getEmail();
51	        int at = email == null ? -1 : email.lastIndexOf('@');
52	        if (at >= 0 && BLOCKED_DOMAINS.contains(email.substring(at + 1).toLowerCase())) {
53	            errors.rejectValue("email", "email.disposable", "must not use a disposable email domain");
54	        }
55	    }
56	}
