19	/**
20	 * Canonicalizes an owner's address: trims and collapses whitespace, upper-cases, and expands the
21	 * common abbreviations ST -> STREET, RD -> ROAD, AVE -> AVENUE (whole words only). Returns
22	 * {@code null} for a {@code null} input; a whitespace-only input normalizes to the empty string.
23	 */
24	final class AddressNormalizer {
25	
26	    private AddressNormalizer() {
27	    }
28	
29	    static String normalize(String address) {
30	        if (address == null) {
31	            return null;
32	        }
33	        return address.strip().replaceAll("\\s+", " ").toUpperCase()
34	            .replaceAll("\\bST\\b", "STREET")
35	            .replaceAll("\\bRD\\b", "ROAD")
36	            .replaceAll("\\bAVE\\b", "AVENUE");
37	    }
38	}
